EMA_Crossover.code:
double ema8 = closes[t], ema21 = closes[t];
double k8 = 2.0 / ({{LOOKBACK_1}} + 1.0), k21 = 2.0 / ({{LOOKBACK_2}} + 1.0);
for(int i=1; i<50 && t-i>=0; i++) {
    ema8 = closes[t-i] * k8 + ema8 * (1.0 - k8);
    ema21 = closes[t-i] * k21 + ema21 * (1.0 - k21);
}
double signal = (ema8 > ema21) ? 1.0 : -1.0;

RSI_Oscillator.code:
double gains = 0, losses = 0;
for(int i=1; i<{{LOOKBACK_1}}+1 && t-i>=0; i++) {
    double diff = closes[t-i+1] - closes[t-i];
    if(diff > 0) gains += diff;
    else losses -= diff;
}
double rs = (losses == 0) ? 100.0 : gains / losses;
double rsi = 100.0 - (100.0 / (1.0 + rs));
double signal = (rsi < 30.0) ? 1.0 : ((rsi > 70.0) ? -1.0 : 0.0);

