Bollinger_Bands.code:
double sma = 0, var = 0;
for(int i=0; i<{{LOOKBACK_1}} && t-i>=0; i++) sma += closes[t-i];
sma /= {{LOOKBACK_1}}.0;
for(int i=0; i<{{LOOKBACK_1}} && t-i>=0; i++) var += pow(closes[t-i] - sma, 2);
double sd = sqrt(var / {{LOOKBACK_1}}.0) + 1e-6;
double upper = sma + 2.0 * sd, lower = sma - 2.0 * sd;
double signal = (closes[t] < lower) ? 1.0 : ((closes[t] > upper) ? -1.0 : 0.0);

