SIMD_OFI.code:
double sum_ofi = 0.0;
for(int i=0; i<{{LOOKBACK_1}} && t-i>=0; i++) {
    double b_pr_curr = closes[t-i] * 0.9995, b_pr_prev = closes[std::max(0, (int)t-i-1)] * 0.9995;
    double a_pr_curr = closes[t-i] * 1.0005, a_pr_prev = closes[std::max(0, (int)t-i-1)] * 1.0005;
    double bid_ofi = (b_pr_curr > b_pr_prev) ? 1000.0 : ((b_pr_curr == b_pr_prev) ? 50.0 : -1000.0);
    double ask_ofi = (a_pr_curr < a_pr_prev) ? 800.0 : ((a_pr_curr == a_pr_prev) ? -50.0 : -800.0);
    sum_ofi += (bid_ofi - ask_ofi);
}
double signal = (sum_ofi > 5000.0) ? 1.0 : ((sum_ofi < -5000.0) ? -1.0 : 0.0);

